head.script:
// 가이드 : validateDataCollect 전체 옵션 샘플 (합성 화면 — JLDFIL25910·ULDFIL52100 골격 참조)

/*
 * 화면 동작
 * 1. 발행기관 정보를 입력하고 「저장」 클릭시 통합 검증 → 확인 → 저장 순으로 진행
 * 2. 국가코드가 대한민국(410)이 아니면 외국국적으로 판단해 우편번호·법인·사업자등록번호 입력을 금지
 * 3. 상호변경내역2 를 입력하면 상호변경내역1 변경일이 선행 필수가 된다
 * 4. 상호변경 이력 그리드는 행 단위로 필수·날짜형식·행 간 중복을 검증
 * 5. 첨부파일 2종의 크기 합계가 100MB 를 넘으면 저장을 막는다
 * 6. 「플래그 검사」는 서버 체크 응답 플래그(DataMap) 검증 공통함수 validateDataMap 데모 —
 *    체크박스로 응답 플래그를 흉내 내고 alert/confirm 형 규칙의 중단 code 동작을 확인한다
 *
 * 담긴 패턴 — $c.validate.validateDataCollect 전 규칙 시연
 * - 동작 옵션        : validateType(alert|mark|all) · checkType(single|multi) · focus · editMode
 * - 기본 규칙        : required · allowChar · ignoreChar · minLength/maxLength · fixLength
 * - byte·자릿수 규칙 : maxLengthB(한/영 혼합 byte) · maxLengthF(정수.소수 자리수)
 * - 숫자 규칙        : num(n/i/f) · fromNum/toNum
 * - format 규칙      : email · date · bizNum · corpNum · urlNoProtocol
 * - 조건부 규칙      : emptyIf(notEquals — 외국국적 입력 금지) · requiredIf(notEmpty — 선행 입력)
 * - 그룹·중복 규칙   : duplicateGroup(폼 결산월) · duplicate(그리드 행 간 중복)
 * - 체크박스 규칙    : checked(약관 동의 3종 — 미체크 "0"/false 도 실패)
 * - 명세 v3 신규     : maxLengthB 객체형(korEng — "한글 N자 영문 M자" 문구, 한글 3byte 환산)
 *                      · required 문구 자동 분기(선택형 "선택하세요"/입력형 "입력하세요")
 *                      · 필드 focus/message · compare · matchValue (미사용 옵션은 검증 함수 주석 예시 참조)
 * - 부가 검사        : $c.util.checkFileTotalSize(첨부 총용량 100MB)
 * - DataMap 플래그   : $c.validate.validateDataMap — 서버 체크 응답 dma 의 "키 값 일치 시 alert/confirm 후 중단 code" 나열 패턴 공통화
 *
 * 참고
 * - required·checked 외 규칙은 빈 값을 통과시킨다. 필수 항목은 required 를 병행 지정한다.
 * - byte 길이(minLengthB/maxLengthB)는 UTF-8 기준(한글 3byte)으로 계산한다.
 * - 그리드 검증은 행 단위로 돌므로 행이 0건이면 실행되지 않는다.
 *   "최소 1건 필수" 는 저장 함수에서 getRowCount() 로 따로 확인한다.
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "SMPVAL10000";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 25
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	// 진입점 표준 오류 처리 — 내부 함수는 예외를 위로 던지고, 진입점의 catch 한 줄로 수렴한다.
	try {
		await scwin.init();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "SMPVAL10000.init" });
	}
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 25
 * @description 초기화. 달력 형식 검증을 걸고 이력 그리드에 데모 행을 넣는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 달력 컴포넌트 id, 데모 데이터 제거
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 달력에 형식 검증을 걸어 둔다. 직접 타이핑한 값도 이 검증을 탄다.
	$c.date.checkCalendarFormat("cal_chgDt1", "yyyyMMdd");

	// 가이드 확인용 데모 행. 실제 화면에서는 조회 결과를 바인딩한다.
	dlt_chgHistory.setJSON([{ chgDt : "20240102", chgNm : "(주)샘플홀딩스", email : "master@sample.co.kr" }]);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_fileUp1_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 정관 찾아보기 클릭. 파일 선택창을 연다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_fileUp1_onclick = function (e) {
	$c.util.onUploadClick(upd_file1);
};

/**
 * @event
 * @name scwin.btn_fileUp2_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 등기부등본 찾아보기 클릭. 파일 선택창을 연다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_fileUp2_onclick = function (e) {
	$c.util.onUploadClick(upd_file2);
};

/**
 * @event
 * @name scwin.upd_file1_onInputValueChange
 * @author Inswave
 * @date 2026. 08. 25
 * @description 정관 파일을 고른 순간 파일명을 화면에 표시한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.upd_file1_onInputValueChange = function (fileName) {
	txt_file1.setValue(fileName);
};

/**
 * @event
 * @name scwin.upd_file2_onInputValueChange
 * @author Inswave
 * @date 2026. 08. 25
 * @description 등기부등본 파일을 고른 순간 파일명을 화면에 표시한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.upd_file2_onInputValueChange = function (fileName) {
	txt_file2.setValue(fileName);
};

/**
 * @event
 * @name scwin.btn_addRow_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 이력 행추가 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_addRow_onclick = function (e) {
	dlt_chgHistory.insertRow();
};

/**
 * @event
 * @name scwin.btn_delRow_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 이력 행삭제 클릭. 선택한 행을 지운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delRow_onclick = async function (e) {
	// focusMode="row" 그리드의 현재 행은 getFocusedRowIndex 로 얻는다(미선택 시 -1).
	const rowIndex = grd_chgHistory.getFocusedRowIndex();

	if (rowIndex < 0) {
		await $c.win.alert("삭제할 행을 선택하세요.");
		return;
	}

	dlt_chgHistory.deleteRow(rowIndex);
};

/**
 * @event
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 저장 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_save_onclick = async function (e) {
	// 진입점 표준 오류 처리 — sbm 통신 오류(이미 알림)·중복 제출 skip 은 handleError 가 선별해 이중 알림이 없다.
	try {
		await scwin.save();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "SMPVAL10000.save" });
	}
};

/**
 * @event
 * @name scwin.btn_reset_onclick
 * @author Inswave
 * @date 2026. 08. 25
 * @description 초기화 버튼 클릭. 입력값을 모두 비운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_reset_onclick = async function (e) {
	if (!await $c.win.confirm("입력한 내용을 모두 지우시겠습니까?")) return;

	dma_corpInfo.reset();
	dlt_chgHistory.removeAll();
	dma_svrCheck.reset();
};

/**
 * @event
 * @name scwin.btn_svrCheck_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description 플래그 검사 버튼 클릭 (validateDataMap 데모)
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_svrCheck_onclick = async function (e) {
	try {
		await scwin.checkSvrFlags();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "SMPVAL10000.checkSvrFlags" });
	}
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 08. 25
 * @description 통합 검증 → 사용자 확인 → 저장 순으로 진행한다.
 *
 * 검증이 먼저다. 확인부터 받으면 실패했을 때 다시 물어야 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
	if (!await scwin.validate()) return;

	if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "저장"))) return;

	const sbmOptions = {
		id : "sbm_saveCorpInfo",
		method : "post",
		action : "/api/sample/smpval/corp-info/save",
		ref : "dma_corpInfo",
		isProcessMsg : false
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	// 중복 실행 가드에 걸려 건너뛴 호출은 responseJSON 이 없다. 실패로 오판하지 않는다.
	if (result?.skipped) return;

	// 실패도 알린다. 그냥 return 하면 사용자는 저장된 줄 안다.
	if (!result.responseJSON?.success) {
		await $c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
		return;
	}

	await $c.win.alert($c.data.getMessage("com_complete_0150", "저장"));
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 08. 25
 * @description 저장 전 통합 검증. validateDataCollect 전 규칙을 한 벌의 options 로 수행한다.
 *
 * 순서 : ① 폼(입력 테이블+약관) → ② 이력 그리드 → ③ 첨부 총용량
 * 개별 if/alert/focus 를 항목마다 쓰지 않는다. 규칙은 전부 fields 로 선언한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - fields 의 컴포넌트 id·규칙·표시명(name), 외국국적 기준 코드(410)
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
	// ① 폼 검증 — 검증 대상은 입력 테이블과 약관 영역을 감싼 컨테이너(grp_input)다.
	//    multi + focus : 실패 항목을 모두 모아 한 번에 알리고 첫 실패 항목에 포커스한다.
	const formOptions = {
		validateType : "alert",  // alert(알림) | mark(req 클래스 마킹) | all(알림+마킹)
		checkType    : "multi",  // single(첫 실패 즉시 중단) | multi(전건 수집 후 취합 알림)
		focus        : true,
		fields : {
			// [기본] 필수 선택 — 선택형 컴포넌트라 "국가코드은(는) 선택하세요." 문구로 자동 분기(명세 §3)
			sbx_nationCd   : { required : true, name : "국가코드" },

			// [byte] 한/영 혼합 byte 제한 — UTF-8 기준(한글 3byte). 객체형(korEng)은 "한글 N자 영문 M자" 문구(명세 §2)
			ipt_corpNm     : { required : true, maxLengthB : 80, name : "발행기관명" },
			ipt_corpAbbrNm : { maxLengthB : { value : 40, msgType : "korEng" }, name : "발행기관 한글약명" },   // "한글 13자 영문 40자" 문구
			ipt_dscnBefCorpNm : { maxLengthB : 100, name : "분할전 법인명" },

			// [문자] 허용 문자 + 최대 길이 (영문 전용 항목은 maxLength 로 글자수 제한)
			ipt_corpEngNm  : { required : true, allowChar : "a-zA-Z0-9 .,()\\-", maxLength : 80, name : "발행기관 영문명" },

			// [조건부 필수] 영문명을 입력했으면 회사속성도 선택해야 한다
			sbx_engAttr    : { requiredIf : { compID : "ipt_corpEngNm", notEmpty : true,
			                                  message : "발행기관 영문명의 회사속성을 선택해주세요." }, name : "영문명 회사속성" },

			// [조건부 금지] 국가코드가 대한민국(410)이 아니면 외국국적 — 아래 3개 항목 입력 금지
			//   notEquals 는 참조 값이 빈 경우(미선택) 조건 불충족으로 처리한다. 미선택은 국가코드 required 소관.
			ipt_zipCd      : { emptyIf : { compID : "sbx_nationCd", notEquals : "410",
			                               message : "외국국적은 우편번호를 입력할 수 없습니다." },
			                   num : "n", fixLength : 5, name : "우편번호" },
			ipt_corpRegNo  : { emptyIf : { compID : "sbx_nationCd", notEquals : "410",
			                               message : "외국국적은 법인등록번호를 입력할 수 없습니다." },
			                   format : "corpNum", name : "법인등록번호" },      // 13자리+검증번호
			ipt_bizRegNo   : { emptyIf : { compID : "sbx_nationCd", notEquals : "410",
			                               message : "외국국적은 사업자등록번호를 입력할 수 없습니다." },
			                   format : "bizNum", name : "사업자등록번호" },     // 10자리+검증번호

			// [형식] URL 은 프로토콜(http:// 등) 제외 입력, 이메일 형식
			ipt_homeUrl    : { format : "urlNoProtocol", name : "홈페이지" },
			ipt_email      : { required : true, format : "email", name : "대표 이메일" },

			// [숫자] 실수 형식 + 정수 3자리.소수 2자리 + 0~100 범위
			ipt_feeRate    : { num : "f", maxLengthF : "3.2", fromNum : 0, toNum : 100, name : "수수료율" },

			// [그룹 중복] 같은 그룹명(settleMonth)을 지정한 필드끼리 값 중복 금지
			sbx_settleMm1  : { required : true, duplicateGroup : "settleMonth", name : "결산월1" },
			sbx_settleMm2  : { duplicateGroup : "settleMonth", name : "결산월2" },

			// [선행 조건] 상호변경내역2 를 입력했으면 내역1 변경일이 먼저 입력되어야 한다
			cal_chgDt1     : { requiredIf : { compID : "ipt_chgNm2", notEmpty : true,
			                                  message : "상호변경내역1 변경일을 먼저 입력해주세요." },
			                   format : "date", name : "상호변경내역1 변경일" },

			// [약관] checked 는 required 와 달리 미체크 값("0"·false)도 실패로 잡는다 — "…동의 해주세요." 문구(명세 §6)
			chk_agreePrivacy : { checked : true, name : "개인정보 처리방침 동의" },
			chk_agreeCollect : { checked : true, name : "개인정보 수집·이용 동의" },
			chk_agreeTerms   : { checked : true, name : "표준코드 서비스 이용약관 동의" }

			// [참고 — 명세 v3 신규 옵션 예시] 이 화면에는 대응 컴포넌트가 없어 주석으로 제공 (validate.xml JSDoc 참조)
			// 분리 입력 필드 포커스(§1)  : ipt_corpRegNo : { format : "corpNum", focus : "ipt_corpRegNo1", name : "법인등록번호" }
			// 특정 값 확인(§5)           : ipt_newYn : { matchValue : { value : "Y", message : "아이디 중복확인 여부를 확인하십시오." },
			//                                            focus : "ipt_integUsrId", name : "중복확인" }   // 미입력도 실패
			// 두 컴포넌트 값 비교(§4)    : acntClsMm1 : { compare : { compareTarget : "acntClsMm2", compareType : "NOT_EQUAL",
			//                                            message : "동일한 결산월이 존재합니다.\n결산월을 확인해주세요!" },
			//                                            focus : "acntClsMm2", name : "결산월" }
			// required 문구 재정의(§5)   : ipt_newYn : { required : true, message : "아이디 중복확인 여부를 확인하십시오." }
		}
	};

	if (!await $c.validate.validateDataCollect(grp_input, formOptions)) return false;

	// ② 그리드 검증 — fields 키는 컬럼ID. duplicate 는 행 간 같은 값 금지.
	//    그리드 검증은 행 단위라 0건이면 실행되지 않는다. 최소 1건은 여기서 확인한다.
	if (dlt_chgHistory.getRowCount() === 0) {
		await $c.win.alert("상호변경 이력을 1건 이상 입력해주세요.");
		return false;
	}

	const gridOptions = {
		validateType : "alert",
		checkType    : "multi",
		focus        : true,
		editMode     : true,   // 실패 셀 포커스 시 편집모드 진입
		fields : {
			chgDt : { required : true, format : "date", duplicate : true, name : "변경일" },
			chgNm : { required : true, maxLengthB : 80, name : "변경 상호" },
			email : { format : "email", name : "담당자 이메일" }
		}
	};

	if (!await $c.validate.validateDataCollect(grd_chgHistory, gridOptions)) return false;

	// ③ 첨부 총용량 — 검증 규칙이 아닌 저장 전 공통 검사. 컴포넌트/File 혼용 배열 허용.
	const sizeRst = $c.util.checkFileTotalSize([upd_file1, upd_file2], 100);

	if (!sizeRst.valid) {
		await $c.win.alert(sizeRst.message);
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.checkSvrFlags
 * @author Inswave
 * @date 2026. 09. 01
 * @description 서버 체크 응답 플래그 검사 데모. validateDataMap 은 rules 를 선언 순서대로 검사해
 *              key 값이 equals 와 일치하면 위반으로 처리한다 — alert 형(기본)은 알림 후 즉시 해당 code 를 반환하고,
 *              confirm 형은 사용자가 취소한 경우에만 code 를 반환한다(확인 시 다음 규칙 계속). 모두 통과하면 0.
 *
 * 실제 화면에서는 체크 서브미션(executeDynamic) 응답을 target DataMap 에 받은 직후 호출한다.
 *  - 예: await scwin.getCheckUrl(...); return $c.validate.validateDataMap(dma_rtnGetCheckUrl, [...]);
 *
 * 복사해 쓸 때 바꿀 곳
 *  - DataMap id·규칙(key/equals/message/code/type), 통과 시 후속 처리
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSvrFlags = async function () {
	const rtnCode = await $c.validate.validateDataMap(dma_svrCheck, [
		{ key : "VALID_STRT_DD", equals : "Y", message : "적용일이 현재일자보다 작습니다. 다시 입력하십시오.", code : 1 },
		// confirm 형 — 확인하면 다음 규칙 계속, 취소하면 code 4 반환
		{ key : "VALID_BF_DD", equals : "Y", type : "confirm", message : "상장일/적용일이 익영업일이 아닙니다. 처리하시겠습니까?", code : 4 },
		{ key : "VALID_CLS_DD", equals : "Y", message : "입력한 일자는 이미 마감처리가 종료된 일자입니다. 다시 입력하십시오.", code : 3 }
	]);

	// 위반 알림은 공통함수가 이미 표시했다 — 반환 code(1/3/4)로 사유별 후속 분기가 가능하다.
	if (rtnCode > 0) return;

	await $c.win.alert("서버 체크 플래그를 모두 통과했습니다. 저장을 진행할 수 있습니다.");
};
